{
  "items": [
    {
      "name": "Polynomial.degree_le_iff_coeff_zero",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Definitions",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (f : Polynomial R) (n : WithBot ℕ), f.degree ≤ n ↔ ∀ (m : ℕ), n < ↑m → f.coeff m = 0"
    },
    {
      "name": "Polynomial.le_natDegree_of_ne_zero",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Operations",
      "kind": "theorem",
      "type": "∀ {R : Type u} {n : ℕ} [inst : Semiring R] {p : Polynomial R}, p.coeff n ≠ 0 → n ≤ p.natDegree"
    },
    {
      "name": "Polynomial.card_mahlerMeasure_le_prod",
      "module_name": "Mathlib.NumberTheory.MahlerMeasure",
      "kind": "theorem",
      "type": "∀ (n : ℕ) (B : NNReal),\n  {p | p.natDegree ≤ n ∧ (Polynomial.map (Int.castRingHom ℂ) p).mahlerMeasure ≤ ↑B}.ncard ≤\n    ∏ i, (2 * ⌊↑(n.choose ↑i) * B⌋₊ + 1)"
    },
    {
      "name": "MvPolynomial.monomial_le_degreeOf",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (i : σ) {f : MvPolynomial σ R} {m : σ →₀ ℕ},\n  m ∈ f.support → m i ≤ MvPolynomial.degreeOf i f"
    },
    {
      "name": "ChevalleyThm.MvPolynomialC.degBound",
      "module_name": "Mathlib.RingTheory.Spectrum.Prime.ChevalleyComplexity",
      "kind": "definition",
      "type": "ℕ → (ℕ → ℕ) → ℕ → ℕ"
    },
    {
      "name": "MvPolynomial.degreeOf_le_totalDegree",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (f : MvPolynomial σ R) (i : σ),\n  MvPolynomial.degreeOf i f ≤ f.totalDegree"
    }
  ]
}
